from rich.console import Console
from rich.panel import Panel
from rich.text import Text
from rich.rule import Rule
from rich import print as rprint

console = Console()

SEVERITY_COLORS = {
    "CRITICAL": "bold red",
    "HIGH": "bold yellow",
    "MEDIUM": "bold cyan",
    "LOW": "bold green",
}


def print_postmortem(raw_text: str):
    """
    Pretty-prints the post-mortem to the terminal using Rich.
    """
    console.print()
    console.print(Rule("[bold white]INCIDENT POST-MORTEM — ONEPORT[/bold white]", style="white"))
    console.print()

    lines = raw_text.strip().split("\n")
    current_section = None

    for line in lines:
        line = line.rstrip()

        # Header fields (TITLE:, DATE:, etc.)
        if line.startswith(("TITLE:", "DATE:", "DURATION:", "SEVERITY:", "IMPACT:")):
            key, _, value = line.partition(":")
            value = value.strip()
            color = SEVERITY_COLORS.get(value, "white") if key == "SEVERITY" else "cyan"
            console.print(f"  [bold white]{key}[/bold white]: [{color}]{value}[/{color}]")

        # Section headers
        elif line.endswith(":") and line.isupper() or (
            line.upper() == line and len(line) > 4 and ":" not in line
        ) or any(line.startswith(h) for h in [
            "SUMMARY", "TIMELINE", "ROOT CAUSE", "CONTRIBUTING", "ACTION ITEMS", "LESSONS"
        ]):
            console.print()
            console.print(f"  [bold yellow]{line}[/bold yellow]")

        # Priority action items
        elif line.startswith("[P"):
            console.print(f"  [bold green]{line}[/bold green]")

        # Owner/Due lines
        elif line.strip().startswith("Owner:"):
            console.print(f"  [dim]{line}[/dim]")

        # Bullet points
        elif line.strip().startswith("•"):
            console.print(f"  [white]{line}[/white]")

        # 5-Whys lines
        elif "→" in line:
            console.print(f"  [cyan]{line}[/cyan]")

        # Timeline lines [HH:MM]
        elif line.strip().startswith("["):
            console.print(f"  [white]{line}[/white]")

        # Everything else
        elif line.strip():
            console.print(f"  {line}")

    console.print()
    console.print(Rule(style="dim"))
    console.print()


def save_to_file(raw_text: str, output_path: str):
    """
    Saves the raw post-mortem text to a .txt file.
    """
    with open(output_path, "w", encoding="utf-8") as f:
        f.write("INCIDENT POST-MORTEM — GENERATED BY ONEPORT\n")
        f.write("=" * 60 + "\n\n")
        f.write(raw_text)
        f.write("\n\n" + "=" * 60)
    console.print(f"  [dim]Saved to: {output_path}[/dim]")